    public static byte[] Definition(DefinitionKind kind) => Decode(kind switch
    {
        DefinitionKind.CapabilityCatalog => DefinitionCapabilityCatalog,
        DefinitionKind.EvaluationCatalog => DefinitionEvaluationCatalog,
        DefinitionKind.Policy => DefinitionPolicy,
        DefinitionKind.Profile => DefinitionProfile,
        DefinitionKind.ProjectManifest => DefinitionProjectManifest,
        DefinitionKind.Workflow => DefinitionWorkflow,
        DefinitionKind.AgentContext => DefinitionAgentContext,
        DefinitionKind.ArtifactDescriptor => DefinitionArtifactDescriptor,
        DefinitionKind.ArtifactProvenance => DefinitionArtifactProvenance,
        DefinitionKind.ArtifactReceipt => DefinitionArtifactReceipt,
        DefinitionKind.PhaseEnvelope => DefinitionPhaseEnvelope,
        DefinitionKind.RunInputSet => DefinitionRunInputSet,
        DefinitionKind.SanitizationAttestation => DefinitionSanitizationAttestation,
        _ => throw new InvalidNativeDefinitionKind()
    });

    static byte[] Decode(string value) => Convert.FromBase64String(value);
}

sealed class InvalidNativeDefinitionKind : Exception;

